<template>
  <main class="ops-workbench">
    <header class="page-header"><div><div class="eyebrow">{{ k('workspaceLabel') }}<span> / </span>{{ k('opsReadOnly') }}</div><h1>{{ k('title') }}</h1><p>{{ k('subtitle') }}</p></div><div class="header-actions"><t-tag :theme="settings?.enabled ? 'success' : 'default'" variant="light">{{ settings ? k(settings.enabled ? 'enabled' : 'disabled') : k('unknown') }}</t-tag><t-button variant="outline" @click="settingsVisible = true">{{ k('settings') }}</t-button><t-button variant="outline" :loading="loading" @click="reload">{{ k('refresh') }}</t-button></div></header>
    <nav class="tabs" :aria-label="k('title')"><button v-for="item in tabs" :key="item" type="button" :class="{ active: tab === item }" :aria-current="tab === item ? 'page' : undefined" @click="changeTab(item)">{{ k(item) }}</button></nav>
    <FilterBar :values="tab === 'records' ? recordDraft : draftFilters" :applied="tab === 'records' ? recordFilters : filters" :records="tab === 'records'" :loading="loading" @change="changeFilter" @period="changePeriod" @apply="applyFilters" @reset="resetFilters" @remove="removeFilter" />
    <p v-if="filters.route === 'technical_followup'" class="scope-note">{{ k('technicalNotice') }}</p>
    <p v-if="filterError" class="error" role="alert">{{ filterError }}</p>
    <div class="scope-strip"><span><span class="scope-dot" />{{ k('scopeShort') }}</span><span v-if="settings?.capture_enabled_at">{{ k('captureSince') }} {{ date(settings.capture_enabled_at) }}</span></div>
    <div v-if="loading" class="loading-state" role="status"><t-loading size="medium" />{{ k('loading') }}</div>
    <section v-else-if="error" class="empty-state panel" role="alert"><h2>{{ k('errorTitle') }}</h2><p>{{ error }}</p><t-button @click="reload">{{ k('retry') }}</t-button></section>
    <template v-else>
      <template v-if="tab === 'overview' && overview">
        <div class="metrics"><article v-for="item in metrics" :key="item.key" class="metric"><div class="metric-label"><span>{{ k(item.key) }}</span><span class="metric-marker" :class="item.key" /></div><strong :class="item.key">{{ item.value.toLocaleString() }}</strong><small v-if="item.key !== 'total'">{{ overview.total ? (item.value / overview.total * 100).toFixed(1) : '0.0' }}%</small><small v-else>{{ k('scope') }}</small><div class="metric-track" aria-hidden="true"><i :class="item.key" :style="{width: `${overview.total ? item.value / overview.total * 100 : 0}%`}" /></div></article></div>
        <div class="distribution-grid"><section v-for="item in distributions" :key="item.key" class="panel" :class="item.key"><h2>{{ k(item.key) }}</h2><p v-if="!Object.keys(item.values).length" class="muted">{{ k('none') }}</p><div v-for="(value, key) in item.values" :key="key" class="distribution"><span class="distribution-label">{{ item.key === 'verdicts' ? labelVerdict(String(key)) : label(String(key)) }}</span><div class="bar" aria-hidden="true"><i :class="String(key)" :style="{ width: `${Object.values(item.values).reduce((sum, n) => sum + n, 0) ? value / Object.values(item.values).reduce((sum, n) => sum + n, 0) * 100 : 0}%` }" /></div><strong>{{ value }}</strong></div></section></div>
        <p class="scope-note">{{ k('supportDenominator') }}</p><OverviewInsights :stats="overview" /><div class="summary"><span>{{ k('pendingTasks') }} <strong>{{ overview.pending_tasks }}</strong></span><span>{{ k('reviewCount') }} <strong>{{ overview.review_count }}</strong></span></div>
      </template>
      <section v-if="tab === 'queue' && overview" class="panel queue-counts"><h2>{{ k('queueStats') }}</h2><div class="queue-count-grid"><button v-for="value in ['human_review','quality_sample','needs_evidence','technical_followup']" :key="value" @click="filterQueue(value)"><span>{{ label(value) }}</span><strong>{{ overview.queue_counts?.[value] || 0 }}</strong></button></div></section>
      <QueuePanel v-if="tab === 'queue'" :runs="runs" :groups="groups" :grouped="grouped && !selectedGroup" :selectedGroup="selectedGroup" @open="openRun" @group="selectGroup" @toggle="toggleGroups" />
      <section v-if="tab !== 'queue'" class="panel list-panel"><div class="section-header"><h2>{{ k(tab === 'overview' ? 'runs' : tab) }}</h2><span class="muted">{{ total }} {{ k('count') }}</span></div><p class="scope-note">{{ k('autoNotice') }}</p>
        <div v-if="!total" class="empty-state"><span class="empty-glyph" aria-hidden="true"><SearchIcon /></span><h3>{{ k('empty') }}</h3><p>{{ k('emptyHint') }}</p></div>
        <div v-else class="table-scroll"><table v-if="tab !== 'records'"><thead><tr><th>{{ k('question') }}</th><th>{{ k('qa_type') }} / {{ k('channel') }}</th><th>{{ k('capture_status') }}</th><th>{{ k('verdict') }}</th><th>{{ k('route') }}</th><th>{{ k('diagnosis') }}</th><th>{{ k('reviewState') }}</th><th>{{ k('time') }}</th><th>{{ k('operation') }}</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td class="question-cell"><span>{{ run.question }}</span><small>{{ run.execution_mode || k('unknown') }}</small></td><td>{{ label(run.qa_type) }}<small>{{ run.channel || k('unknown') }}</small></td><td><StatusBadge :value="run.capture_status" /></td><td><StatusBadge :value="run.analysis?.report.verdict" verdict /></td><td>{{ label(run.analysis?.route) }}</td><td><StatusBadge :value="run.analysis?.status || 'pending'" /></td><td>{{ label(run.review_state) }}</td><td>{{ date(run.started_at) }}</td><td><button type="button" class="link-button" @click="openRun(run.id)">{{ k('detail') }}</button></td></tr></tbody></table>
        <table v-else><thead><tr><th>{{ k('caseVersion') }}</th><th>{{ k('machineOriginal') }}</th><th>{{ k('target') }}</th><th>{{ k('reviewAction') }}</th><th>{{ k('verdict') }} / {{ k('causeCategory') }}</th><th>{{ k('reviewReason') }}</th><th>{{ k('reviewer') }}</th><th>{{ k('created') }}</th><th>{{ k('operation') }}</th></tr></thead><tbody><tr v-for="review in reviews" :key="review.id"><td class="question-cell">{{ review.question }}<small>v{{ review.analysis_version }} · {{ review.analysis_id }}</small></td><td><template v-if="review.target === 'answer'">{{ labelVerdict(review.machine_verdict) }}</template><template v-else><p v-for="(cause,i) in review.machine_causes || []" :key="i">{{ label(cause.category) }} · {{ label(cause.status) }}<small>{{ cause.summary }}</small></p><span v-if="!review.machine_causes?.length">{{ k('noCause') }}</span></template></td><td>{{ k(review.target === 'answer' ? 'answerTarget' : 'causeTarget') }}<small>{{ review.analysis_id }}</small></td><td><StatusBadge :value="review.action" /></td><td>{{ review.target === 'answer' ? labelVerdict(review.verdict) : label(review.verdict) }}<small v-if="review.cause_category">{{ label(review.cause_category) }}</small></td><td class="reason-cell">{{ review.reason }}</td><td>{{ review.reviewer_id }}</td><td>{{ date(review.created_at) }}</td><td><button type="button" class="link-button" @click="openRun(review.run_id, review.analysis_id)">{{ k('detail') }}</button></td></tr></tbody></table></div>

      </section>
        <footer v-if="total" class="pagination"><t-button variant="outline" :disabled="page <= 1" @click="changePage(page - 1)">{{ k('previous') }}</t-button><span>{{ k('page') }} {{ page }} / {{ Math.max(1, Math.ceil(total / pageSize)) }}</span><t-button variant="outline" :disabled="page * pageSize >= total" @click="changePage(page + 1)">{{ k('next') }}</t-button></footer>
    </template>
    <SettingsDrawer :visible="settingsVisible" @close="settingsVisible = false" @saved="settingsSaved" />
    <DetailDrawer :runID="activeRun" :analysisID="activeAnalysis" :enabled="!!settings?.enabled" @close="closeRun" @changed="reload" />
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { SearchIcon } from 'tdesign-icons-vue-next'
import { MessagePlugin } from 'tdesign-vue-next'
import { useAuthStore } from '@/stores/auth'
import { getOpsSettings, getOpsOverview, getOpsRuns, getOpsReviews, getOpsGroups, type OpsGroup, opsErrorCode, type OpsSettings, type OpsOverview, type OpsRun, type OpsReview, type OpsFilters } from '@/api/knowledge-ops'
import { buildFilters } from './state'
import { useOpsText } from './locales'
import StatusBadge from './StatusBadge.vue'
import FilterBar from './FilterBar.vue'
import QueuePanel from './QueuePanel.vue'
import OverviewInsights from './OverviewInsights.vue'
import SettingsDrawer from './SettingsDrawer.vue'
import DetailDrawer from './DetailDrawer.vue'
const { k, label, labelVerdict, date } = useOpsText()
const router = useRouter(); const route = useRoute(); const auth = useAuthStore()
const tabs = ['overview', 'queue', 'records'] as const
type Tab = typeof tabs[number]
const tab = ref<Tab>(tabs.includes(route.query.tab as Tab) ? route.query.tab as Tab : 'overview')
const settings = ref<OpsSettings>(); const overview = ref<OpsOverview>(); const runs = ref<OpsRun[]>([]); const reviews = ref<OpsReview[]>([])
const loading = ref(false); const error = ref(''); const settingsVisible = ref(false); const filterError = ref(''); const page = ref(1); const pageSize = 20; const total = ref(0)
const activeAnalysis = computed(() => typeof route.query.analysis === 'string' ? route.query.analysis : '')
const groups = ref<OpsGroup[]>([]); const grouped = ref(true); const selectedGroup = ref('')
const recordDraft = reactive({review_from: '', review_to: '', target: '', action: '', reviewer_id: '', review_search: ''}); const recordFilters = ref<OpsFilters>({})
const activeRun = computed(() => typeof route.query.run === 'string' ? route.query.run : '')
const blankFilters = () => ({ from: '', to: '', qa_type: '', channel: '', capture_status: '', route: '', verdict: '', search: '', risk: '', cause_category: '' })
const draftFilters = reactive(blankFilters()); const filters = ref<OpsFilters>({}); let token = 0
const metrics = computed(() => [{ key: 'total', value: overview.value?.total || 0 }, { key: 'complete', value: overview.value?.complete || 0 }, { key: 'partial', value: overview.value?.partial || 0 }, { key: 'missing', value: overview.value?.missing || 0 }])
const distributions = computed(() => [{ key: 'diagnosisStates', values: overview.value?.diagnosis_status || {} }, { key: 'verdicts', values: overview.value?.by_verdict || {} }, { key: 'routing', values: overview.value?.by_route || {} }])
async function reload() {
  const current = ++token; loading.value = true; error.value = ''
  const params = { ...(tab.value === 'records' ? recordFilters.value : filters.value), ...(selectedGroup.value && tab.value === 'queue' ? {group_key: selectedGroup.value} : {}), page: page.value, page_size: pageSize, ...(tab.value === 'queue' ? { view: 'queue' as const } : {}) }
  try {
    const [config, stats, result] = await Promise.all([getOpsSettings(), tab.value !== 'records' ? getOpsOverview(tab.value === 'queue' ? {...filters.value, route: undefined} : filters.value) : Promise.resolve(undefined), tab.value === 'records' ? getOpsReviews(params) : tab.value === 'queue' && grouped.value && !selectedGroup.value ? getOpsGroups(params) : getOpsRuns(params)])
    if (current !== token) return
    settings.value = config; overview.value = stats; total.value = result.total
    if (tab.value === 'records') { reviews.value = result.items as OpsReview[]; runs.value = [] } else if (tab.value === 'queue' && grouped.value && !selectedGroup.value) { groups.value = result.items as OpsGroup[]; runs.value = []; reviews.value = [] } else { runs.value = result.items as OpsRun[]; groups.value = []; reviews.value = [] }
  } catch (failure) { if (current === token) { error.value = k(opsErrorCode(failure)); runs.value = []; reviews.value = []; overview.value = undefined; total.value = 0 } }
  finally { if (current === token) loading.value = false }
}
function changeFilter(key: string, value: string) { const draft = tab.value === 'records' ? recordDraft : draftFilters; if (key in draft) (draft as Record<string, string>)[key] = value }
function changePeriod(from: string, to: string) { if (tab.value === 'records') {recordDraft.review_from = from; recordDraft.review_to = to} else {draftFilters.from = from; draftFilters.to = to} }
function removeFilter(key: string) {
  const applied = {...(tab.value === 'records' ? recordFilters.value : filters.value)} as Record<string,string>
  const keys = key === 'period' ? (tab.value === 'records' ? ['review_from','review_to'] : ['from','to']) : [key]
  keys.forEach(item => {delete applied[item]; changeFilter(item, '')})
  if (tab.value === 'records') recordFilters.value = applied; else filters.value = applied
  selectedGroup.value = ''; page.value = 1; void reload()
}
function applyFilters() {
  filterError.value = ''
  if (tab.value === 'records') { if (recordDraft.review_from && recordDraft.review_to && new Date(recordDraft.review_from) >= new Date(recordDraft.review_to)) {filterError.value = k('dateInvalid'); return}; recordFilters.value = buildFilters(recordDraft); page.value = 1; void reload(); return }
  selectedGroup.value = ''
  if (draftFilters.from && draftFilters.to && new Date(draftFilters.from) >= new Date(draftFilters.to)) { filterError.value = k('dateInvalid'); return }
  filters.value = buildFilters(draftFilters); page.value = 1; void reload()
}
function resetFilters() { if (tab.value === 'records') Object.keys(recordDraft).forEach(key => {recordDraft[key as keyof typeof recordDraft] = ''}); else Object.assign(draftFilters, blankFilters()); applyFilters() }
function changeTab(value: Tab) { if (tab.value === value) return; tab.value = value; page.value = 1; void router.replace({ query: { ...route.query, tab: value } }); void reload() }
function changePage(value: number) { page.value = value; void reload() }
function openRun(id: string, analysis?: string) { void router.replace({ query: { ...route.query, run: id, analysis } }) }
function selectGroup(key: string) {selectedGroup.value = key; page.value = 1; void reload()}
function toggleGroups() {grouped.value = !grouped.value; selectedGroup.value = ''; page.value = 1; void reload()}
function filterQueue(value: string) {draftFilters.route = filters.value.route === value ? '' : value; applyFilters()}
function closeRun() { const query = { ...route.query }; delete query.run; delete query.analysis; void router.replace({ query }) }
function settingsSaved(value: OpsSettings) { settings.value = value; MessagePlugin.success(k('settingsSaved')); void reload() }
watch(() => auth.selectedTenantId, () => { token++; settings.value = undefined; settingsVisible.value = false; closeRun(); groups.value = []; selectedGroup.value = ''; page.value = 1; void reload() })
watch(() => route.query.tab, value => { if (tabs.includes(value as Tab) && value !== tab.value) { tab.value = value as Tab; page.value = 1; void reload() } })
onMounted(reload)
</script>
<style scoped>
