x;color:var(--td-text-color-primary)}.list-panel{margin-top:12px;padding:22px 0 0;overflow:hidden}.section-header{display:flex;align-items:baseline;justify-content:space-between;padding:0 22px}.section-header h2{margin:0;font-size:16px}.list-panel>.scope-note{padding:0 22px;margin:10px 0 20px}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:1080px;font-size:13px;text-align:left}th{font-weight:500;background:color-mix(in srgb,var(--td-bg-color-secondarycontainer) 55%,var(--td-bg-color-container));color:var(--td-text-color-secondary);white-space:nowrap;font-size:12px}th,td{padding:16px 14px;border-bottom:1px solid var(--td-component-stroke);vertical-align:top}th:first-child,td:first-child{padding-left:22px}td:last-child,th:last-child{padding-right:22px}tbody tr:last-child td{border-bottom:0}td small{display:block;color:var(--td-text-color-secondary);margin-top:6px;font-size:12px;max-width:180px;overflow-wrap:anywhere}.question-cell{max-width:270px;min-width:180px;font-weight:500}.question-cell small{font-weight:400}.question-cell>span{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.reason-cell{max-width:280px;min-width:150px;white-space:pre-wrap;overflow-wrap:anywhere}.link-button{border:0;padding:0;background:transparent;color:var(--td-brand-color-7);font:inherit;font-weight:500;cursor:pointer;white-space:nowrap;min-height:32px}.link-button:hover{text-decoration:underline}tbody tr:hover{background:var(--td-bg-color-container-hover)}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:14px;margin-top:18px;font-size:12px;color:var(--td-text-color-secondary)}.empty-state{text-align:center;padding:48px 24px;color:var(--td-text-color-secondary)}.empty-state h3{font-size:15px;color:var(--td-text-color-primary);font-weight:500}.empty-state p{font-size:13px}.empty-glyph{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;background:var(--td-bg-color-secondarycontainer);border-radius:12px;font-size:28px}.loading-state{display:flex;justify-content:center;align-items:center;gap:12px;min-height:280px}.error{color:var(--td-error-color)}button:focus-visible{outline:2px solid var(--td-brand-color);outline-offset:3px}.queue-counts{margin:20px 0;padding:0;background:none;border:0}.queue-counts h2{font-size:13px;color:var(--td-text-color-secondary);margin:0 0 12px}.queue-count-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.queue-count-grid button{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border:1px solid var(--td-component-stroke);border-radius:10px;background:var(--td-bg-color-container);font:inherit;color:var(--td-text-color-primary);cursor:pointer;transition:border-color .15s}.queue-count-grid button:hover{border-color:var(--td-brand-color)}.queue-count-grid strong{font-size:26px;font-weight:600}.queue-count-grid button:first-child strong{color:var(--td-error-color-6)}
